import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(x) for x in data[1:1 + n]]
    vals = sorted(x for x in a if x != 0)
    m = len(vals)
    rank = {v: i for i, v in enumerate(vals)}
    zeros = n - m
    tgt = [-1] * n
    mis = 0
    for p in range(n):
        if a[p] != 0:
            tgt[p] = rank[a[p]]
            if tgt[p] != p:
                mis += 1
    seen = [False] * n
    for p in range(m, n):
        q = p
        while a[q] != 0:
            seen[q] = True
            q = tgt[q]
    cycles = 0
    for p in range(n):
        if a[p] != 0 and tgt[p] != p and not seen[p]:
            cycles += 1
            q = p
            while not seen[q]:
                seen[q] = True
                q = tgt[q]
    if cycles and zeros == 0:
        print(-1)
    else:
        print(mis + cycles)

